const parts = msg.topic.split("/");
const known = new Set(["cpu_load", "power_w", "fan_rpm", "inlet_temp", "outlet_temp", "module_temp", "supply_temp", "return_temp", "rx_power_dbm", "tx_power_dbm", "pre_fec_ber", "current_a", "load_pct", "cooling_pct"]);
const segment = /^[A-Za-z0-9_-]+$/;
const reject = (reason) => {
    const counts = flow.get("rejected") || {};
    counts[reason] = (counts[reason] || 0) + 1;
    flow.set("rejected", counts);
    return [null, { payload: reason, topic: msg.topic }];
};
if (parts.length !== 6 || parts[0] !== "dc" || !parts.slice(1).every((part) => segment.test(part))) {
    return reject("topic");
}
const metric = parts[5];
if (!known.has(metric)) {
    return reject("metric");
}
let body = msg.payload;
if (typeof body === "string" || Buffer.isBuffer(body)) {
    try {
        body = JSON.parse(body.toString());
    } catch (err) {
        return reject("json");
    }
}
const value = Number(body && body.value);
const ts = Number(body && body.ts);
if (!Number.isFinite(value) || !Number.isFinite(ts)) {
    return reject("value");
}
const skewSeconds = Math.abs(Date.now() / 1000 - ts);
if (skewSeconds > 86400) {
    return reject("skew");
}
msg.payload = [new Date(ts * 1000).toISOString(), parts.slice(1, 5).join("/"), metric, value];
return [msg, null];

const rows = msg.payload;
msg.query = "INSERT INTO telemetry (ts, device_key, metric, value) SELECT * FROM unnest($1::timestamptz[], $2::text[], $3::text[], $4::float8[])";
msg.params = [
    rows.map((row) => row[0]),
    rows.map((row) => row[1]),
    rows.map((row) => row[2]),
    rows.map((row) => row[3])
];
node.status({ fill: "green", shape: "dot", text: rows.length + " rows" });
return msg;
